output_text:
[
  {
    "id": "no_hand_carry",
    "text": "Customers are prohibited from carrying selected merchandise by hand and must avoid the hand-full state.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_in_use": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper must take the available entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "cart_in_use": "hasCart"
      },
      "events": {
        "cart_acquired": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "cart_in_use"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_acquired"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items may only be picked up while the shopper is already holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cart_in_use"
            ]
          },
          "post": "cart_in_use"
        },
        "item_taken_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "cart_in_use"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_taken_without_cart"
    }
  },
  {
    "id": "leave_cart_only_return_bay",
    "text": "A cart may be put down only in the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_in_use": "hasCart"
      },
      "events": {
        "cart_left_at_return_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "cart_left_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "cart_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_elsewhere"
    }
  },
  {
    "id": "return_taken_cart",
    "text": "After taking a cart, the shopper is obliged to return it to the return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_in_use": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_acquired": {
          "pre": "PICKUP_CART",
          "post": "cart_in_use"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_bay",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_acquired",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper may exit only after the cart is visibly parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_attempt": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_attempt",
          {
            "not": "cart_parked_in_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_exit_corridor",
    "text": "Carts are prohibited from being pushed along the bottom exit corridor; they may only leave that area by going north into the aisles.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_corridor": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_use": "hasCart"
      },
      "events": {
        "cart_pushed_along_exit_corridor": {
          "pre": {
            "and": [
              "cart_in_use",
              "bottom_exit_corridor",
              {
                "or": [
                  "E",
                  "W",
                  "S",
                  "EXIT"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_pushed_along_exit_corridor"
    }
  },
  {
    "id": "reenter_front_after_return",
    "text": "After returning the cart at the return bay, the shopper must go back to the front entrance cell before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "front_entrance": "at(0,5)",
        "cart_in_use": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_bay",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        },
        "arrive_front_entrance_without_cart": {
          "pre": {
            "and": [
              "front_entrance",
              "cart_parked_in_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_returned",
      "discharge": "arrive_front_entrance_without_cart"
    }
  }
]
